import { sanitizeExpense, sanitizeHome, sanitizePlace } from '../core.js';
export class FirebaseTripRepository {
  constructor(client,{tripSlug,tripName='Đà Lạt 2026',home=null}){this.client=client;this.tripSlug=tripSlug;this.tripName=tripName;this.bootstrapHome=home;this.tripId=tripSlug;this.role=null;this.user=null;this.unsubscribe=[]}
  async connect(){await this.client.init();this.user=await this.client.ensureSession();if(!this.user)return null;this.role=await this.ensureTripAndMembership();return {user:this.user,tripId:this.tripId,role:this.role}}
  canEdit(){return this.role==='owner'||this.role==='editor'}
  async ensureTripAndMembership(){const tripRef=this.client.doc('trips',this.tripSlug),memberRef=this.client.doc('trips',this.tripSlug,'members',this.user.id);return this.client.runTransaction(async(tx)=>{const tripSnap=await tx.get(tripRef);if(!tripSnap.exists()){const home=sanitizeHome(this.bootstrapHome||{});tx.set(tripRef,{slug:this.tripSlug,name:this.tripName,homeName:home.address||'Home',homeLat:home.lat??null,homeLng:home.lng??null,publicJoin:true,ownerUid:this.user.id,createdAt:this.client.serverTimestamp(),updatedAt:this.client.serverTimestamp()});tx.set(memberRef,memberPayload(this.user,'owner',this.client.serverTimestamp()));return 'owner'}const trip=tripSnap.data(),memberSnap=await tx.get(memberRef);if(memberSnap.exists())return memberSnap.data().role||'viewer';if(!trip.publicJoin)throw new Error('Trip không cho phép thành viên mới tham gia.');let role='editor';if(!trip.ownerUid){role='owner';tx.update(tripRef,{ownerUid:this.user.id,updatedAt:this.client.serverTimestamp()})}tx.set(memberRef,memberPayload(this.user,role,this.client.serverTimestamp()));return role})}
  async loadAll(){const tripRef=this.client.doc('trips',this.tripSlug);const [tripSnap,placesSnap,expensesSnap,votesSnap,membersSnap]=await Promise.all([this.client.getDoc(tripRef),this.client.getDocs(this.client.collection('trips',this.tripSlug,'places')),this.client.getDocs(this.client.collection('trips',this.tripSlug,'expenses')),this.client.getDocs(this.client.collection('trips',this.tripSlug,'votes')),this.client.getDocs(this.client.collection('trips',this.tripSlug,'members'))]);if(!tripSnap.exists())throw new Error('Trip không tồn tại.');const trip={id:tripSnap.id,...tripSnap.data()};return {trip,home:sanitizeHome({address:trip.homeName||'Home',lat:trip.homeLat,lng:trip.homeLng}),places:placesSnap.docs.map(d=>fromPlaceDoc(d.id,d.data())).sort(byCreatedAsc),expenses:expensesSnap.docs.map(d=>fromExpenseDoc(d.id,d.data())).sort(byCreatedDesc),votes:votesSnap.docs.map(d=>({id:d.id,place_id:d.data().placeId,user_id:d.data().userId,created_at:toIso(d.data().createdAt)})),members:membersSnap.docs.map(d=>fromMemberDoc(d.id,d.data())).sort((a,b)=>String(a.joined_at).localeCompare(String(b.joined_at)))}}
  async savePlace(place){const ref=this.client.doc('trips',this.tripSlug,'places',place.id);await this.client.setDoc(ref,toPlaceDoc(place,this.user.id,this.client.serverTimestamp()),{merge:true});return sanitizePlace({...place,updatedAt:new Date().toISOString()})}
  async deletePlace(id){await this.client.deleteDoc(this.client.doc('trips',this.tripSlug,'places',id))}
  async saveExpense(expense){const ref=this.client.doc('trips',this.tripSlug,'expenses',expense.id);await this.client.setDoc(ref,toExpenseDoc(expense,this.user.id,this.client.serverTimestamp()),{merge:true});return sanitizeExpense({...expense,updatedAt:new Date().toISOString()})}
  async deleteExpense(id){await this.client.deleteDoc(this.client.doc('trips',this.tripSlug,'expenses',id))}
  async setVote(placeId,shouldVote){const id=`${placeId}_${this.user.id}`,ref=this.client.doc('trips',this.tripSlug,'votes',id);if(shouldVote)await this.client.setDoc(ref,{placeId,userId:this.user.id,createdAt:this.client.serverTimestamp()});else await this.client.deleteDoc(ref)}
  async updateMemberRole(userId,role){if(this.role!=='owner')throw new Error('Chỉ owner được đổi quyền thành viên.');if(userId===this.user.id)throw new Error('Owner không thể tự hạ quyền của chính mình.');if(!['editor','viewer'].includes(role))throw new Error('Role không hợp lệ.');await this.client.updateDoc(this.client.doc('trips',this.tripSlug,'members',userId),{role,updatedAt:this.client.serverTimestamp()})}
  subscribe(onChange){this.unsubscribe.forEach(stop=>stop());this.unsubscribe=['places','expenses','votes','members'].map(name=>this.client.onSnapshot(this.client.collection('trips',this.tripSlug,name),()=>onChange({table:name}),(error)=>onChange({table:name,error})));return()=>{this.unsubscribe.forEach(stop=>stop());this.unsubscribe=[]}}
}
function memberPayload(user,role,timestamp){return {userId:user.id,role,displayName:user.displayName||user.user_metadata?.full_name||'',email:user.email||'',photoURL:user.photoURL||user.user_metadata?.avatar_url||'',joinedAt:timestamp,updatedAt:timestamp}}
function fromMemberDoc(id,row){return {trip_id:null,user_id:id,role:row.role||'viewer',joined_at:toIso(row.joinedAt),profile:{id,full_name:row.displayName||'',email:row.email||'',avatar_url:row.photoURL||''}}}
function fromPlaceDoc(id,row){return sanitizePlace({id,name:row.name,address:row.address,category:row.category,priority:row.priority,note:row.note,lat:row.lat,lng:row.lng,distanceMeters:row.distanceMeters,durationSeconds:row.durationSeconds,routeSource:row.routeSource,source:row.source,createdAt:toIso(row.createdAt),updatedAt:toIso(row.updatedAt)})}
function toPlaceDoc(p,userId,timestamp){return {name:p.name,address:p.address||'',category:p.category,priority:p.priority,note:p.note||'',lat:p.lat,lng:p.lng,distanceMeters:p.distanceMeters??null,durationSeconds:p.durationSeconds??null,routeSource:p.routeSource||'fallback',source:p.source||'manual',createdBy:p.createdBy||userId,updatedBy:userId,createdAt:p.createdAt||timestamp,updatedAt:timestamp}}
function fromExpenseDoc(id,row){return sanitizeExpense({id,payer:row.payer,category:row.category,amountVnd:Number(row.amountVnd),note:row.note,createdAt:toIso(row.createdAt),updatedAt:toIso(row.updatedAt)})}
function toExpenseDoc(e,userId,timestamp){return {payer:e.payer,category:e.category,amountVnd:e.amountVnd,note:e.note||'',createdBy:e.createdBy||userId,updatedBy:userId,createdAt:e.createdAt||timestamp,updatedAt:timestamp}}
function toIso(value){if(!value)return new Date().toISOString();if(typeof value.toDate==='function')return value.toDate().toISOString();if(typeof value==='string')return value;return new Date().toISOString()}
function byCreatedAsc(a,b){return String(a.createdAt||'').localeCompare(String(b.createdAt||''))}function byCreatedDesc(a,b){return String(b.createdAt||'').localeCompare(String(a.createdAt||''))}
